import{_ as i,o as a,c as t,a5 as r}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Verification","description":"","frontmatter":{},"headers":[],"relativePath":"feature/credit-price-csv-import/test.md","filePath":"feature/credit-price-csv-import/test.md"}'),o={name:"feature/credit-price-csv-import/test.md"};function n(s,e,l,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h1><ul><li>Actual benchmark CSV: BOM, quoted values, both operations, one operation, blank steps, zero price, escaped quote/comma/newline and Excel-safe profile accepted.</li><li>Reject wrong/duplicate/reordered/missing header, malformed quotes/UTF8, oversized file, empty data, &gt;2 rows, duplicate/unsupported operations, wrong schema, negative/fraction/scientific/overflow/unsafe integer, invalid GUID/profile, dimensions/steps/timestamp. Return record/field codes; no writes on preview.</li><li>Forbidden/inactive/missing actor denied before parsing/writing; malformed upload and request parts return structured errors, never generic 500.</li><li>Two-row apply is atomic: stale second operation or audit failure leaves first unchanged. Race against manual price edit uses the same advisory lock, compares revisions and fails without lost updates. Opposite CSV order does not deadlock.</li><li>Preserve enabled/disabled, initialize absent price disabled, leave other operations and old reservations/history unchanged. Exact SHA mismatch rejected. Repeated changed apply is stale; refreshed no-op creates no price version.</li><li>Browser: file picker, auto-preview, compare/provenance, invalid/stale/large file, double-click/async selection races, preserved file and explicit re-preview, success refresh, vi/en/light/dark/375px/keyboard, no CSV code or HTML execution.</li><li>Use isolated DB/mocks only; do not apply a real benchmark price, run AI or seed shared data. No new executable tests in src or committed local fixtures/reports.</li></ul><h2 id="results-—-2026-10-28" tabindex="-1">Results — 2026-10-28 <a class="header-anchor" href="#results-—-2026-10-28" aria-label="Permalink to &quot;Results — 2026-10-28&quot;">​</a></h2><ul><li>59 assertions passed in the local Java harness: actual benchmark export, malformed quotes/UTF8/numeric/metadata cases, active/Admin guard, SHA/revision checks, multipart preview/apply binding (including string revision JSON), size limits, missing/malformed request and pre-controller multipart 413 mapping.</li><li>PostgreSQL 16 QA, isolated container/random loopback port: actual transactions, atomic two-price changes, stale second operation, audit failure rollback, two opposite-order imports racing (one succeeds, one stale), import racing against the existing manual-price API, retention of old accepted-job prices, no-op versions, enabled preservation, absent price disabled, provenance audit and active-user check. Only the private QA schema was initialized/reset; no demo/shared DB connection.</li><li>Browser passed file-picker selection, immediate preview, source metadata, exact current/proposed display, real multipart transport to a memory-only QA API, double-click guard, table/cache refresh, no-op, invalid/oversized file, stale revision with explicit re-preview, late-response selection race and error focus. New panel checked in vi/en/light/dark and widths 375/768/1440.</li><li>Changed Web files pass ESLint with zero warnings; production build passes. Backend compilation and resolved Commons CSV runtime tested. New test code, fixtures, screenshots and logs remain ignored under keep-local-only.</li><li>Existing AdminCrawlConfigServiceTest regression also passed (5 tests).</li></ul><h2 id="manual-test-and-rollout" tabindex="-1">Manual test and rollout <a class="header-anchor" href="#manual-test-and-rollout" aria-label="Permalink to &quot;Manual test and rollout&quot;">​</a></h2><ol><li>Restart Business using Maven so the new Commons CSV dependency and controller are loaded; reload/rebuild Web. Do not run an init or migration for this feature.</li><li>Sign in as Admin and open <code>/admin/credit-prices</code>.</li><li>In the benchmark tool, choose representative eligible reports and export <code>credit_recommendations.csv</code>. Import that file using the new toolbar action.</li><li>Verify current/proposed unit credits, source report/profile/dimensions/steps, export time, revision and enabled state. Only two image operations are supported in CSV v1. Width/height/steps are provenance, not extra price dimensions.</li><li>Apply explicitly. Changed prices receive new append-only revisions; unchanged amounts do not create versions. Existing accepted AI jobs keep their old price.</li><li>Preview a file, edit one target price separately, then apply: expect 409 and no partial update. Check the file again, review the new current values, then apply.</li><li>The importer uses the Web price editing range 0..9007199254740991, a 64 KiB limit and at most two records. Oversized Int64 exports are rejected with an explicit error; their values are never rounded to JavaScript numbers.</li></ol><h2 id="db-impact" tabindex="-1">DB impact <a class="header-anchor" href="#db-impact" aria-label="Permalink to &quot;DB impact&quot;">​</a></h2><ul><li><code>ai_credit_operation_prices</code>: INSERT only for changed/absent imported operations; preserve enabled state (absent=false) and retain all old revisions.</li><li><code>audit_logs</code>: one audit per accepted apply, including SHA256, source report/profile, benchmark metadata, previous state and updated count; same transaction as prices.</li><li>No schema, MongoDB, init, migration, seeder, wallet, subscription or limit changes. No real prices or shared data were changed by implementation/QA.</li></ul>',8)])])}const h=i(o,[["render",n]]);export{m as __pageData,h as default};
